      dialog = 3,
      music = "205_XuMo_Second",
      renwu = "npc",
      sentence = "虽然和许墨进行过模拟答辩，但当他真正坐在我的面前，我实在很难将他完全当做一个陌生的考官。",
      next = {12}
    },
