      idx = 2,
      male = 2,
      music = "205_XuMo_Second",
      renming = "许墨",
      renwu = "npc",
      sentence = "这个案例，是一个在领地中斗争失败的猕猴家族。它们流浪于公路和村庄，靠人类投喂存活。",
